def clean(df):
    df = df.copy()
    # body_mass_g is stored as text: strip thousands separators, coerce to number
    s = (df['body_mass_g'].astype(str)
         .str.replace(',', '', regex=False)
         .str.strip())
    mass = pd.to_numeric(s, errors='coerce')
    # values written with an extra scale (e.g. 3650000 instead of 3650): rescale into range
    def rescale(v):
        if pd.isna(v):
            return v
        while v > 6500 and v % 1000 == 0:
            v = v / 1000.0
        if v < 2500 or v > 6500:
            return float('nan')
        return v
    df['body_mass_g'] = mass.apply(rescale)
    # normalize label variants (not needed for this question, but harmless)
    df['species'] = df['species'].replace({'Gentto': 'Gentoo', 'Adeile': 'Adelie'})
    df['island'] = df['island'].str.capitalize()
    return df

def answer(df):
    g = df.dropna(subset=['sex', 'body_mass_g']).groupby('sex')['body_mass_g'].mean()
    return {str(k): float(v) for k, v in g.items()}
